    name = os.path.basename(path)
    m = re.match(rf"{re.escape(snapshot_basename)}(\d+)\.amuse$", name)
    if m is None:
        raise ValueError(
            f"File '{path}' does not match snapshot pattern "
            f"'{snapshot_basename}###.amuse'"
        )
    return int(m.group(1))
